+import os, sys, time
+import torch
+from torch.utils.cpp_extension import load_inline
+
+src_cuda = open('attention.cu').read()
+src_cpp = open('binding.cpp').read()
+
+extra_flags = []
+if os.path.exists('build_flags.json'):
+    import json
+    extra_flags = json.load(open('build_flags.json')).get('extra_cuda_cflags', [])
+
+mod = load_inline(
+    name='attention',
+    cpp_sources=[src_cpp],
+    cuda_sources=[src_cuda],
+    functions=['attention_forward'],
+    with_cuda=True,
+    extra_cuda_cflags=['-gencode', 'arch=compute_86,code=sm_86'] + extra_flags,
+    verbose=False,
+)
+
+def ref_attn(q, k, v, causal):
+    # q,k,v: [B,H,S,D] bf16 (k,v maybe [B,KVH,S,D])
+    B, H, S, D = q.shape
+    KVH = k.shape[1]
+    scale = D ** -0.5
+    qf = q.float()
+    kf = k.float()
+    vf = v.float()
+    out = torch.empty_like(qf)
+    for h in range(H):
+        kvh = h // (H // KVH)
+        scores = qf[:, h] @ kf[:, kvh].transpose(-1, -2) * scale  # [B,S,S]
+        if causal:
+            mask = torch.tril(torch.ones(S, S, dtype=torch.bool, device=q.device))
+            scores = scores.masked_fill(~mask, float('-inf'))
+        p = torch.softmax(scores, dim=-1)
+        out[:, h] = p @ vf[:, kvh]
+    return out.to(q.dtype)
+
+torch.manual_seed(0)
+dev = 'cuda'
+for (B, H, KVH, S, causal) in [
+    (2, 16, 16, 512, False),
+    (2, 16, 16, 512, True),
+    (2, 16, 16, 1024, False),
+    (2, 16, 16, 1024, True),
+    (1, 16, 4, 512, False),
+    (1, 16, 4, 512, True),
+    (2, 16, 16, 4096, False),
+    (2, 16, 16, 4096, True),
+    (1, 16, 16, 333, False),
+    (1, 16, 16, 333, True),
+]:
+    q = torch.randn(B, H, S, 128, device=dev, dtype=torch.bfloat16)
+    k = torch.randn(B, KVH, S, 128, device=dev, dtype=torch.bfloat16)
+    v = torch.randn(B, KVH, S, 128, device=dev, dtype=torch.bfloat16)
+    out = mod.attention_forward(q, k, v, causal)
+    ref = ref_attn(q, k, v, causal)
+    err = (out.float() - ref.float()).abs().max().item()
+    thresh = 2 * 2 ** -8 + 1e-3  # ~0.0088
+    status = "OK " if err < thresh else "FAIL"
+    print(f"{status} B={B} H={H} KVH={KVH} S={S} causal={causal} maxerr={err:.6f} thr={thresh:.6f}")
+    if err >= thresh:
+        sys.exit(1)
+
+# quick timing
+for (B, H, KVH, S, causal) in [(8, 16, 16, 1024, False), (8, 16, 16, 1024, True), (2, 16, 16, 4096, False)]:
+    q = torch.randn(B, H, S, 128, device=dev, dtype=torch.bfloat16)
+    k = torch.randn(B, KVH, S, 128, device=dev, dtype=torch.bfloat16)
+    v = torch.randn(B, KVH, S, 128, device=dev, dtype=torch.bfloat16)
+    for _ in range(3):
+        out = mod.attention_forward(q, k, v, causal)
+    torch.cuda.synchronize()
+    n = 10
+    t0 = time.time()
+    for _ in range(n):
+        out = mod.attention_forward(q, k, v, causal)
+    torch.cuda.synchronize()
+    ms = (time.time() - t0) / n * 1e3
+    flops = 4 * B * H * S * S * 128 / (2 if causal else 1)
+    print(f"B={B} H={H} S={S} causal={causal}: {ms:.3f} ms, {flops/ms/1e9:.1f} TFLOPS")
+print("ALL PASS")


