// ---- Probe 2: mma with hand-built fragments, verify against reference.
// Q[16][16] = r*16+k ; K[8][16] (row=n, col=k) = n*8+k ; S = Q*K^T.
__global__ void probe_mma(float* out, int* ok) {
  int lane = threadIdx.x % 32;
  int g = lane >> 2, l = lane & 3;
  // A fragment: a0=(Q[g][2l],Q[g][2l+1]) a1=(Q[g][2l+8],Q[g][2l+9])
  //            a2=(Q[g+8][2l],Q[g+8][2l+1]) a3=(Q[g+8][2l+8],Q[g+8][2l+9])
  float Q[16][16];
  for (int r = 0; r < 16; r++) for (int c = 0; c < 16; c++) Q[r][c] = (float)(r * 16 + c);
  float K[8][16];
  for (int n = 0; n < 8; n++) for (int k = 0; k < 16; k++) K[n][k] = (float)(n * 8 + k);
  uint32_t a[4];
