  a[1] = pack2(Q[g][2 * l + 8], Q[g][2 * l + 9]);
  a[2] = pack2(Q[g + 8][2 * l], Q[g + 8][2 * l + 1]);
  a[3] = pack2(Q[g + 8][2 * l + 8], Q[g + 8][2 * l + 9]);
  // B fragment (candidate from CUTLASS BLayout): b0=(K[l/8][l%8],K[l/8][l%8+8])
  // b1=(K[l/8+4][l%8],K[l/8+4][l%8+8])
  int r8 = lane / 8, c8 = lane % 8;
  uint32_t b[2];
  b[0] = pack2(K[r8][c8], K[r8][c8 + 8]);
  b[1] = pack2(K[r8 + 4][c8], K[r8 + 4][c8 + 8]);
  float d[4] = {0.f, 0.f, 0.f, 0.f};
  mma_m16n8k16(d, a, b, d);
  // reference S[r][n] = sum_k Q[r][k]*K[n][k]
  float S[16][8];
  for (int r = 0; r < 16; r++) for (int n = 0; n < 8; n++) {
    float s = 0.f;
    for (int k = 0; k < 16; k++) s += Q[r][k] * K[n][k];
    S[r][n] = s;
  }
  // expected D: d0=S[g][2l], d1=S[g][2l+1], d2=S[g+8][2l], d3=S[g+8][2l+1]
  float exp[4] = {S[g][2 * l], S[g][2 * l + 1], S[g + 8][2 * l], S[g + 8][2 * l + 1]};
  int base = lane * 4;
  for (int j = 0; j < 4; j++) {
    out[base + j] = d[j];
    if (d[j] != exp[j]) *ok = 0;
  }
}

