// mode: 0 = A unit at (ap,ah), B=0 ; 1 = B unit at (bp,bh), A=0 ;
// 2 = both units.
__global__ void probe_unit2(int mode, int ap, int ah, int bp, int bh, float* out) {
  int lane = threadIdx.x % 32;
  uint32_t a[4] = {0, 0, 0, 0};
  uint32_t b[2] = {0, 0};
  uint16_t one = __bfloat16_as_ushort(__float2bfloat16(1.f));
  if (mode == 0 || mode == 2) {
    if (ah == 0) a[ap] = mk(one, 0); else a[ap] = mk(0, one);
  }
  if (mode == 1 || mode == 2) {
    if (bh == 0) b[bp] = mk(one, 0); else b[bp] = mk(0, one);
  }
  float c[4] = {0.f, 0.f, 0.f, 0.f};
  float d[4];
  mma_m16n8k16(d, a, b, c);
  for (int j = 0; j < 4; j++) out[lane * 4 + j] = d[j];
