int main() {
  float* d_out; cudaMalloc(&d_out, 32 * 4 * 4);
  float h[128];
  // A unit only, each (ap,ah)
  for (int ap = 0; ap < 4; ap++) for (int ah = 0; ah < 2; ah++) {
    probe_unit2<<<1, 32>>>(0, ap, ah, 0, 0, d_out);
    cudaMemcpy(h, d_out, 32 * 4 * 4, cudaMemcpyDeviceToHost);
    float mx = 0; int ml = -1, mj = -1;
    for (int l = 0; l < 32; l++) for (int j = 0; j < 4; j++) if (h[l*4+j] != 0) { mx = h[l*4+j]; ml = l; mj = j; }
    printf("A(reg%d,h%d) alone: nonzero D at lane %d reg %d = %g\n", ap, ah, ml, mj, mx);
  }
  for (int bp = 0; bp < 2; bp++) for (int bh = 0; bh < 2; bh++) {
    probe_unit2<<<1, 32>>>(1, 0, 0, bp, bh, d_out);
    cudaMemcpy(h, d_out, 32 * 4 * 4, cudaMemcpyDeviceToHost);
    float mx = 0; int ml = -1, mj = -1;
    for (int l = 0; l < 32; l++) for (int j = 0; j < 4; j++) if (h[l*4+j] != 0) { mx = h[l*4+j]; ml = l; mj = j; }
    printf("B(reg%d,h%d) alone: nonzero D at lane %d reg %d = %g\n", bp, bh, ml, mj, mx);
