    cudaMemcpy(h, d_out, 32 * 4 * 4, cudaMemcpyDeviceToHost);
    printf("both A(reg%d,h0) B(reg0,h0): lane0 d=[%g %g %g %g], lane8=[%g %g %g %g], lane16=[%g %g %g %g]\n",
           ap, h[0], h[1], h[2], h[3], h[32], h[33], h[34], h[35], h[64], h[65], h[66], h[67]);
  }
  return 0;
}

